//! O esquema do ERP de exemplo: as tabelas (cada entidade com a tabela dos itens ou do
//! histórico, ligada por `mestre_id`) e as telas. Feito uma vez com o resto do exemplo.

/// Uma tabela: o nome e os campos (nome, tipo do Field).
pub struct Tabela {
    pub nome: &'static str,
    pub campos: &'static [(&'static str, &'static str)],
}

/// Uma tela: o form, o módulo, a entidade, o tipo (`Cad`, `Lista`, `Consulta`, `Hist`), a
/// tabela do `cdsMestre`, a do `cdsItens`, o campo da busca e o form do cadastro.
pub struct Tela {
    pub form: &'static str,
    pub modulo: &'static str,
    pub entidade: &'static str,
    pub tipo: &'static str,
    pub mestre: &'static str,
    pub itens: &'static str,
    pub busca: &'static str,
    pub busca_itens: &'static str,
    pub cadastro: &'static str,
    pub documento: bool,
    pub parceiro: &'static str,
}

const CAD: &[(&str, &str)] = &[("id", "auto_inc"), ("codigo", "string"), ("nome", "string"), ("ativo", "boolean"), ("criado_em", "date"), ("observacao", "string")];
const CAD_HIST: &[(&str, &str)] = &[("id", "auto_inc"), ("mestre_id", "integer"), ("data", "date"), ("descricao", "string"), ("responsavel", "string")];
const DOC: &[(&str, &str)] = &[("id", "auto_inc"), ("numero", "integer"), ("data", "date"), ("parceiro", "string"), ("valor_total", "currency"), ("situacao", "string"), ("observacao", "string")];
const DOC_ITENS: &[(&str, &str)] = &[("id", "auto_inc"), ("mestre_id", "integer"), ("item", "string"), ("quantidade", "integer"), ("valor_unitario", "currency"), ("valor_total", "currency")];

